def evaluate(expr: str) -> float:
    tokens: list[str] = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit() or ch == '.':
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif ch in '+-*/()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"unexpected character {ch!r}")
    pos = 0

    def peek() -> str | None:
        return tokens[pos] if pos < len(tokens) else None

    def take() -> str:
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expression() -> float:
        value = term()
        while peek() in ('+', '-'):
            op = take()
            rhs = term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def term() -> float:
        value = factor()
        while peek() in ('*', '/'):
            op = take()
            rhs = factor()
            value = value * rhs if op == '*' else value / rhs
        return value

    def factor() -> float:
        tok = peek()
        if tok == '-':
            take()
            return -factor()
        if tok == '+':
            take()
            return factor()
        if tok == '(':
            take()
            value = expression()
            if take() != ')':
                raise ValueError("expected ')'")
            return value
        if tok is None:
            raise ValueError("unexpected end of expression")
        return float(take())

    result = expression()
    if pos != len(tokens):
        raise ValueError("unexpected trailing input")
    return result
```

