def decode_string(s: str) -> str:
    stack: list[tuple[str, int]] = []
    current = ''
    k = 0
    for ch in s:
        if ch.isdigit():
            k = k * 10 + int(ch)
        elif ch == '[':
            stack.append((current, k))
            current, k = '', 0
        elif ch == ']':
            prev, times = stack.pop()
            current = prev + current * times
        else:
            current += ch
